<h2 class="sr-only">Phác thảo giao diện màu Form thêm / sửa sân (quản trị) — Sân Nhóm H</h2>
<div style="font-family:Arial,Helvetica,sans-serif;border:0.5px solid #E1E8E3;border-radius:12px;overflow:hidden;display:flex;background:#FFFFFF;">
    <div style="width:150px;background:#0F5C33;padding:16px 12px;flex-shrink:0;">
        <div style="font-size:14px;font-weight:700;color:#FFFFFF;margin-bottom:20px;line-height:1.3;">Sân Nhóm H<br><span style="font-size:10px;font-weight:400;color:#9FCBAE;">Admin</span></div>
        <div style="display:flex;flex-direction:column;gap:2px;font-size:12px;">
            <div style="display:flex;align-items:center;gap:8px;padding:8px 10px;color:#BFE0CC;"><i class="ti ti-chart-bar" style="font-size:15px;" aria-hidden="true"></i>Dashboard</div>
            <div style="display:flex;align-items:center;gap:8px;padding:8px 10px;border-radius:6px;background:rgba(255,255,255,.14);color:#FFFFFF;"><i class="ti ti-building" style="font-size:15px;" aria-hidden="true"></i>Sân &amp; cơ sở</div>
            <div style="display:flex;align-items:center;gap:8px;padding:8px 10px;color:#BFE0CC;"><i class="ti ti-calendar-event" style="font-size:15px;" aria-hidden="true"></i>Đơn đặt sân</div>
            <div style="display:flex;align-items:center;gap:8px;padding:8px 10px;color:#BFE0CC;"><i class="ti ti-users" style="font-size:15px;" aria-hidden="true"></i>Người dùng</div>
            <div style="display:flex;align-items:center;gap:8px;padding:8px 10px;color:#BFE0CC;"><i class="ti ti-news" style="font-size:15px;" aria-hidden="true"></i>Nội dung</div>
            <div style="display:flex;align-items:center;gap:8px;padding:8px 10px;color:#BFE0CC;"><i class="ti ti-settings" style="font-size:15px;" aria-hidden="true"></i>Cài đặt</div>
        </div>
    </div>
    <div style="flex:1;padding:18px;min-width:0;background:#F7FAF8;">
        <div style="font-size:10.5px;color:#6B7A70;margin-bottom:8px;">Sân &amp; cơ sở &gt; Thêm sân mới</div>
        <div style="font-size:15px;font-weight:700;color:#16241C;margin-bottom:16px;">Thêm sân mới</div>

        <div style="background:#FFFFFF;border:0.5px solid #E1E8E3;border-radius:10px;padding:16px;margin-bottom:12px;">
            <div style="font-size:11.5px;font-weight:700;color:#16241C;margin-bottom:14px;">Thông tin cơ bản</div>
            <div style="display:grid;grid-template-columns:1fr 1fr;gap:12px;margin-bottom:12px;">
                <div>
                    <div style="font-size:11px;color:#3A453E;margin-bottom:4px;">Tên sân *</div>
                    <div style="height:34px;border-radius:8px;border:0.5px solid #C7D3CA;display:flex;align-items:center;padding:0 10px;font-size:12px;color:#8A968F;">VD: Sân cầu lông số 3</div>
                </div>
                <div>
                    <div style="font-size:11px;color:#3A453E;margin-bottom:4px;">Cơ sở *</div>
                    <div style="height:34px;border-radius:8px;border:0.5px solid #C7D3CA;display:flex;align-items:center;justify-content:space-between;padding:0 10px;font-size:12px;color:#16241C;">CS Bình Thạnh<i class="ti ti-chevron-down" style="font-size:14px;color:#6B7A70;" aria-hidden="true"></i></div>
                </div>
            </div>
            <div style="display:grid;grid-template-columns:1fr 1fr 1fr;gap:12px;margin-bottom:12px;">
                <div>
                    <div style="font-size:11px;color:#3A453E;margin-bottom:4px;">Loại môn *</div>
                    <div style="height:34px;border-radius:8px;border:0.5px solid #C7D3CA;display:flex;align-items:center;justify-content:space-between;padding:0 10px;font-size:12px;color:#16241C;">Cầu lông<i class="ti ti-chevron-down" style="font-size:14px;color:#6B7A70;" aria-hidden="true"></i></div>
                </div>
                <div>
                    <div style="font-size:11px;color:#3A453E;margin-bottom:4px;">Sức chứa</div>
                    <div style="height:34px;border-radius:8px;border:0.5px solid #C7D3CA;display:flex;align-items:center;padding:0 10px;font-size:12px;color:#16241C;">4 người</div>
                </div>
                <div>
                    <div style="font-size:11px;color:#3A453E;margin-bottom:4px;">Trạng thái</div>
                    <div style="height:34px;border-radius:8px;border:0.5px solid #C7D3CA;display:flex;align-items:center;justify-content:space-between;padding:0 10px;font-size:12px;color:#16241C;">Hoạt động<i class="ti ti-chevron-down" style="font-size:14px;color:#6B7A70;" aria-hidden="true"></i></div>
                </div>
            </div>
            <div>
                <div style="font-size:11px;color:#3A453E;margin-bottom:4px;">Mô tả &amp; tiện ích</div>
                <div style="height:60px;border-radius:8px;border:0.5px solid #C7D3CA;padding:8px 10px;font-size:11.5px;color:#8A968F;">Sàn gỗ đạt chuẩn thi đấu, đèn LED, có phòng thay đồ...</div>
            </div>
        </div>

        <div style="background:#FFFFFF;border:0.5px solid #E1E8E3;border-radius:10px;padding:16px;margin-bottom:14px;">
            <div style="font-size:11.5px;font-weight:700;color:#16241C;margin-bottom:12px;">Hình ảnh sân</div>
            <div style="display:flex;gap:10px;">
                <div style="width:80px;height:64px;border-radius:8px;background:#E6F0FA;display:flex;align-items:center;justify-content:center;position:relative;"><i class="ti ti-photo" style="font-size:20px;color:#2563EB;" aria-hidden="true"></i><span style="position:absolute;bottom:3px;left:3px;background:#178A4C;color:#fff;font-size:8px;padding:1px 5px;border-radius:10px;">Ảnh chính</span></div>
                <div style="width:80px;height:64px;border-radius:8px;background:#E6F5EB;display:flex;align-items:center;justify-content:center;"><i class="ti ti-photo" style="font-size:20px;color:#178A4C;" aria-hidden="true"></i></div>
                <div style="width:80px;height:64px;border-radius:8px;border:1.5px dashed #C7D3CA;display:flex;flex-direction:column;align-items:center;justify-content:center;gap:3px;color:#8A968F;"><i class="ti ti-upload" style="font-size:17px;" aria-hidden="true"></i><span style="font-size:9.5px;">Tải ảnh</span></div>
            </div>
        </div>

        <div style="display:flex;gap:10px;">
            <div style="height:36px;padding:0 20px;border-radius:8px;background:#F97316;display:flex;align-items:center;font-size:12px;color:#fff;font-weight:600;">Lưu sân</div>
            <div style="height:36px;padding:0 20px;border-radius:8px;border:0.5px solid #C7D3CA;background:#FFF;display:flex;align-items:center;font-size:12px;color:#3A453E;">Hủy</div>
        </div>
    </div>
</div>